  ["FXAA_CMAA_LABEL"] = { "画像ベースの手法", 0xe9dab29f, "." },
  ["FX_VOLUME"] = { "効果音", 0xf6f9bfd5, "." },
  ["FactionDescription:21"] = { "この活気ある港町は、Blackwater RaidersのBaron Revilgazが治めている。Bloodsail Buccaneersとは不倶戴天の敵であり、Steamwheedle Cartelの一員。", 0x7e9b81b0, "." },
  ["FactionDescription:2586"] = { "元はEastern Kingdoms全域の交易を円滑にするために設立されたACAは、今では世界中のAlliance軍への補給路を維持している。", 0x8036c9b7, "." },
  ["FactionDescription:2587"] = { "Hordeの堅牢な補給網が、Kalimdorとその先への急速な拡大を支えている。", 0xd5dd6387, "." },
  ["FactionDescription:2634"] = { "空は赤く染まり、血への渇きがあなたの感覚を圧倒する！", 0x81534b1e, "." },
  ["FactionDescription:2641"] = { "急ぎ結成されたドルイドの集団で、AllianceとHordeの双方と協力してNightmare Incursionsを食い止めようとしている。", 0x5bdc18b7, "." },
  ["FactionDescription:2679"] = { "Lordaeronの王に仕えることを誓った、聖なるウォリアーたちの修道会。", 0x40c7b261, "." },
  ["FactionDescription:270"] = { "このトロールたちはYojamba Isleにやって来て、Zul'Gurubで蘇った血の神とそのAtal'aiのプリーストたちに立ち向かう助けを募っている。", 0x407992c7, "." },
  ["FactionDescription:2719"] = { "Cenarion Scoutsは、Azerothの自然を探検し守ることに打ち込む、自然を愛する若者たちである。", 0x44ac6d4a, "." },
  ["FactionDescription:2740"] = { "世界で最も強大な魔術師たちからなる精鋭集団であり、魔法の国Dalaranを率いる魔導師の統治評議会。", 0x7a314310, "." },
  ["FactionDescription:2747"] = { "Barkskinは堕落に染まっていない数少ないfurbolgの部族の一つで、Hyjalに調和を取り戻すため、霊的な遺産を守ることに身を捧げている。", 0xcc6cd07b, "." },
  ["FactionDescription:2758"] = { "Shadowgale Forestの秘密主義のドルイドたち。Zephras Isleの他のどの勢力とも離れて、独自に活動している。", 0xb676b03d, "." },
  ["FactionDescription:2765"] = { "Mount Hyjalの守護と保全を託されたCenarion Circleのこの分派は、悪の勢力を押し返そうとする者なら誰でも歓迎する。", 0x34140e4c, "." },
  ["FactionDescription:2778"] = { "Windshapersは、Zephras IsleのSkyborneの民を導くシャーマン的な霊的指導者である。彼らはエレメントを敬い、Skywallにおけるshen'doreiの生き方を守るため、エレメントの次元の本質をより深く理解しようとしている。", 0x79baf3bf, "." },
  ["FactionDescription:2779"] = { "High Orderは、Eldre'ThalasのHighborneの魔導師たちの末裔であるSkyborneである。Skywallの領域で過去10,000年を過ごしたHigh Orderの者たちは、祖先の古き秘術の知識を取り戻そうとしている。", 0xdb7a7bd9, "." },
  ["FactionDescription:2782"] = { "偽りの預言者を裏切ったために追放された、かつてのTwilight's Hammerの一員たち。彼らは自らの道を切り開こうとしている。", 0xb0d166e2, "." },
  ["FactionDescription:2787"] = { "Earthen Ringは、Horde寄りのシャーマンとドルイドのゆるやかな集まりであり、Azerothの自然の均衡を保ち育もうとしている。", 0x3293070e, "." },
  ["FactionDescription:2797"] = { "ナイトエルフ社会の精鋭たち。", 0xd684bc84, "." },
  ["FactionDescription:2798"] = { "トロールの国に忠誠を誓うDarkspear Raidersは、祖先の地Darkspear Islandsの支配をめぐってTheramore Expeditionary Forceと戦っている。", 0xae4311e4, "." },
  ["FactionDescription:2799"] = { "自らの都市に忠実な支持者であるTheramore Expeditionary Forceは、いわゆるDarkspear Islandsの支配をめぐってDarkspear Raidersと戦っている。", 0x1bb82cf1, "." },
  ["FactionDescription:2819"] = { "ナイトエルフ社会の強大な看守と執行官からなる組織。広大な地下牢獄網からいかなる脅威も逃さぬよう、常に目を光らせている。", 0x56b24689, "." },
  ["FactionDescription:2826"] = { "Stormwindの騎兵隊から追放された者たち。かつての騎手である彼らは東海岸沿いの未開の地で新たに出発し、住まいと新たな関係、交易路を築いた。", 0xd6617460, "." },
  ["FactionDescription:2827"] = { "Steamwheedle Cartelの有力な一翼であるこの港には、東の海の交易路を股にかける船乗りや裏路地の商人たちが集まっている。", 0xcf8710c6, "." },
  ["FactionDescription:349"] = { "この盗賊と暗殺者のギルドは、並外れた腕前を持つ者だけを仲間に迎え入れる。Syndicateとは誓い合った宿敵。", 0xe15addc5, "." },
  ["FactionDescription:369"] = { "Steamwheedle Cartelの本拠地であり、ゴブリン屈指の技師、錬金術師、商人たちが暮らす地。", 0x6bc27bf5, "." },
  ["FactionDescription:47"] = { "このAllianceの首都は、Dun Moroghのドワーフたちの誇りである。King Magniの居城。", 0x7338a738, "." },
  ["FactionDescription:470"] = { "Steamwheedle Cartelの一員であるこのゴブリンの町は、Barrensで商品やサービスを取引したい者に中立の安息地を提供している。", 0xd92b7fb2, "." },
  ["FactionDescription:471"] = { "Allianceの一員ではないが、Aerie PeakのドワーフたちはAllianceに門戸を開き、Hordeを敵とみなしている。", 0xff3c6dd2, "." },
  ["FactionDescription:509"] = { "League of Arathorは、Stormwindにいる後援者のため、Arathi Basinの失われた土地を取り戻そうとしている。", 0x1ec818e3, "." },
  ["FactionDescription:510"] = { "Defilersは、Hordeのため、Arathi Basinの貴重な資源を手に入れようとしている。", 0x0a18bac0, "." },
  ["FactionDescription:529"] = { "Scourgeの脅威からAzerothを守ることに力を注ぐ組織。Argent Dawnの拠点はEasternとWestern Plaguelandsにある。", 0x4113163d, "." },
  ["FactionDescription:530"] = { "この追放されたトロールの部族は、ThrallとHordeに力を合わせた。今はDurotarを故郷とし、同盟者であるオークと共に暮らしている。", 0x3ea5477c, "." },
  ["FactionDescription:54"] = { "かつてGnomereganに住んでいた者たち。今はIronforgeで亡命生活を送り、Allianceと手を結んでいる。", 0x067f29fe, "." },
  ["FactionDescription:576"] = { "堕落を免れた最後のfurbolgの部族の一つとして、Timbermawは霊的な生き方を守り、同胞の苦しみを終わらせようとしている。", 0xe2692542, "." },
  ["FactionDescription:577"] = { "この交易所はSteamwheedle Cartelのゴブリンが運営しており、Winterspringの主要な交易路が交わる地点にある。", 0xa62dc357, "." },
  ["FactionDescription:589"] = { "人里離れて暮らすナイトエルフの小集団で、Winterspring一帯でwintersaberを育て、調教している。", 0x4f149356, "." },
  ["FactionDescription:59"] = { "Thorium Brotherhoodのドワーフたちは卓越した職人技の体現者であり、Blackrock Mountainの秘密を解き明かそうと心血を注いでいる。", 0xd74f4abb, "." },
  ["FactionDescription:609"] = { "Cenarion Circleのドルイドは自然の守護者であり、静かなMoongladeに住んでいる。", 0x09a580e2, "." },
  ["FactionDescription:630"] = { "Un'Goro Craterのravasaurは恐ろしく危険だが、一部の者はそれを手なずける方法を身につけた。", 0x8770841e, "." },
  ["FactionDescription:68"] = { "Sylvanas Windrunnerに率いられたForsakenは、Hordeと危うい同盟を結び、Ruins of Lordaeronの地下深くにこの首都を築いた。", 0xde70e660, "." },
  ["FactionDescription:69"] = { "ナイトエルフが暮らすAllianceの首都で、Teldrassilの島にある。月の女祭司Tyrande Whisperwindが治めている。", 0x7c7ef884, "." },
  ["FactionDescription:70"] = { "主に人間からなる犯罪組織で、おもにAlterac MountainsとHillsbrad Foothillsを拠点に活動している。", 0x039ecfd7, "." },
  ["FactionDescription:72"] = { "人間の力が残る最後の砦の一つであるこのAllianceの首都は、幼き王Anduin Wrynnが治めている。", 0x1a805474, "." },
  ["FactionDescription:729"] = { "Frostwolf Clanは、Stormpike ExpeditionのドワーフたちをAlterac Valleyから追い出そうとしている。", 0xb1085726, "." },
  ["FactionDescription:730"] = { "StormpikeのドワーフたちはAlterac Valleyに居を構え、Frostwolfのオークと激しい戦いを繰り広げている。", 0xf10b0cba, "." },
  ["FactionDescription:749"] = { "このエレメンタルたちはAzsharaの東の島々に住み着いている。Ragnarosの軍勢とは誓い合った宿敵。", 0x6fb36621, "." },
  ["FactionDescription:76"] = { "Thrallが築いたこのHordeの首都には、Durotarの誇り高きオークの氏族が数多く暮らしている。", 0x86291572, "." },
  ["FactionDescription:809"] = { "かつて強大だったエルフの生き残りで、Dire Maulに住み、今なお大いなる秘密に通じた賢き者たち。", 0x63e9a14a, "." },
  ["FactionDescription:81"] = { "Cairne Bloodhoofは、この壮大なHordeの首都から自らの民、誇り高きトーレンを率いている。", 0xfed3b47e, "." },
  ["FactionDescription:87"] = { "血に飢えたこの海賊たちは、外洋を行く多くの商人にとっての災いである。Booty Bayの宿敵。", 0x7ad652c1, "." },
  ["FactionDescription:889"] = { "Warsong Clanの猛々しいオークたち。Warsong GulchでSilverwing Sentinelsと戦いを繰り広げている。", 0xdfb1cd3c, "." },
  ["FactionDescription:890"] = { "Ashenvaleの揺るぎなき守り手たち。Warsong GulchでWarsong Outridersと戦いを繰り広げている。", 0xa1c33f03, "." },
  ["FactionDescription:909"] = { "奇妙なものや並外れたものを見せる旅の見世物市。Elwynn ForestやMulgoreでよく見かける。", 0x4339ac1f, "." },
  ["FactionDescription:910"] = { "Bronze Dragonflightの末裔は時の守護者であり、定命の種族にはほとんど関心を払わない。", 0x83782a84, "." },
  ["FactionDescription:92"] = { "このcentaurたちはDesolaceの南部に住み着いている。Magram Centaurとは不倶戴天の敵。", 0x1b4b2304, "." },
  ["FactionDescription:93"] = { "このcentaurたちはDesolaceの東部に住み着いている。Gelkis Centaurとは不倶戴天の敵。", 0xc63dbc46, "." },
})
